# Using Better Auth with Encore.ts for Authentication
created: undefined, last updated: 2026-04-14, [Read more](https://encore.dev/docs/ts/develop/integrations/better-auth)

## Connect to Encore's auth handler
Wire Better Auth into Encore's authentication system so you can use `auth: true` on any API endpoint:
```
handler.ts
import { APIError, Gateway } from "encore.dev/api";
import { authHandler } from "encore.dev/auth";
import { Header } from "encore.dev/api";
import { auth } from "./auth";
interface AuthParams {
authorization: Header<"Authorization">;
}
interface AuthData {
userID: string;
}
const handler = authHandler<AuthParams, AuthData>(
async (params) => {
const session = await auth.api.getSession({
headers: new Headers({
authorization: params.authorization,
}),
});
if (!session) {
throw APIError.unauthenticated("invalid session");
}
return { userID: session.user.id };
}
);
